-- MIGRATION 01 : copie fidèle des 44 fiches JSON dans Supabase.
-- Sans suppression, sans écrasement des fiches déjà importées, sans modification des avis.
-- À exécuter dans Supabase > SQL Editor, avec le rôle postgres.

begin;
create table if not exists public.characters (
 character_id text primary key,
 name text not null,
 role text not null default '',
 kind text not null check (kind in ('team','common','vesper','silk','makoto','plurk','naphria')),
 episode text,
 image text,
 legacy_path text,
 info jsonb not null default '{}'::jsonb,
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now()
);
alter table public.characters enable row level security;
revoke all on public.characters from anon,authenticated;
grant select on public.characters to anon,authenticated;
drop policy if exists "Lecture publique des fiches" on public.characters;
create policy "Lecture publique des fiches" on public.characters for select to anon,authenticated using (true);
-- La création et la modification par les joueurs seront ajoutées dans une étape séparée.
-- Conserver les identifiants : les avis existants continuent à pointer vers les mêmes clés.
on conflict (character_id) do nothing;
-- La table opinion_characters est conservée pour la compatibilité avec les avis.
select character_id from public.characters
on conflict (character_id) do nothing;
commit;

-- Vérification : 44 fiches attendues, aucune opinion supprimée.
select (select count(*) from public.characters) as fiches_en_base,
       (select count(*) from public.character_opinions) as avis_conserves,
       (select count(*) from public.characters c where not exists
         (select 1 from public.opinion_characters o where o.character_id=c.character_id)) as fiches_sans_autorisation_avis;
