insert into public.characters(character_id,name,role,kind,episode,image,legacy_path,info)
values
('team:makoto','Makoto','Samouraï des rues','team',null,'images/Makoto.jpeg','PJ/Team-Makoto-Samourai.jpeg','{"nom":"Makoto","role":"Samouraï des rues","identite_civile":"Inconnue","metatype":"Ork","affiliation":"TEAM","statut":"Actif","description":"Samouraï des rues et membre de l''équipe de Vesper, Makoto est un combattant de peu de mots. Calme, efficace et fiable, il préfère agir plutôt que démontrer ses capacités. Lorsque la situation exige une intervention physique, il répond présent sans discours inutile. Son passé et son équipement restent à préciser.","premiere_apparition":"VESPER_002"}'::jsonb),
('team:naphria','Naphria','Expert en démolition','team',null,'images/Naphria.jpeg','PJ/Team-Naphria-Expert en démolition.jpeg','{"nom":"Naphria","role":"Expert en démolition","identite_civile":"Inconnue","metatype":"Inconnu","affiliation":"TEAM","statut":"Active","description":"Naphria est une spécialiste des explosifs qui travaille régulièrement avec Vesper et son équipe.\n\nPrécise et réfléchie, elle maîtrise suffisamment son domaine pour employer la force nécessaire sans provoquer de dégâts superflus. Elle privilégie les interventions calculées plutôt que les démonstrations spectaculaires.\n\nPour Naphria, les explosifs sont avant tout des outils dont l''efficacité dépend de la manière dont on les utilise.","premiere_apparition":"VESPER_002"}'::jsonb),
('team:plurk','Plurk','Rigger','team',null,'images/Plurk.jpeg','PJ/Team-Plurk-Rigger.jpeg','{"nom":"Plurk","role":"Rigger","identite_civile":"Inconnue","metatype":"Troll","affiliation":"TEAM","statut":"Actif","description":"Plurk est un troll rigger qui travaille régulièrement aux côtés de Vesper et de son équipe.\n\nMéthodique, attentif et compétent, il possède une capacité particulièrement appréciable dans les Ombres : anticiper les difficultés avant qu''elles ne deviennent de véritables problèmes.\n\nMalgré son apparence imposante, Plurk se distingue avant tout par son sens de l''observation et sa réflexion.\n\nIl possède également un humour assez particulier, que Vesper juge discutable. Silk semble néanmoins trouver quelques ressemblances entre leurs deux façons de plaisanter.","premiere_apparition":"VESPER_002"}'::jsonb),
('team:silk','Silk','Face / Négociatrice','team',null,'images/Silk.jpeg','PJ/Team-Silk-Face.jpeg','{"identite_civile":"Alyssa Argent, Kagami Aya (鏡 綾)","metatype":"Elfe","affiliation":"TEAM","statut":"Active","description":"Négociatrice spécialisée dans la persuasion, les relations humaines et l''obtention d''informations. Sœur jumelle de Vesper, avec lequel elle forme un duo complémentaire.","nom":"Silk","role":"Face / Négociatrice","premiere_apparition":"VESPER_001"}'::jsonb),
('team:vesper','Vesper','Gunman','team',null,'images/Vesper.jpeg','PJ/Team-Vesper-Gunman.jpeg','{"identite_civile":"Kagami Ren (鏡 蓮)","metatype":"Elfe","affiliation":"TEAM","statut":"Actif","description":"Pistolero adepte spécialisé dans le combat armé et la protection rapprochée. Vesper privilégie la précision, la maîtrise de soi et l''efficacité plutôt que les démonstrations de force. Armé d''un Ares Predator VI, il suit un code d''honneur inspiré du Bushidō, qu''il s''efforce de respecter même dans les Ombres.\n\nCourtois, calme et particulièrement attentif à son apparence, il forme avec Silk, sa sœur jumelle, un duo aux compétences complémentaires. Là où elle privilégie la négociation, il intervient lorsque les arguments ne suffisent plus.","premiere_apparition":"VESPER_001"}'::jsonb),
('contact:ash','Ash','Personne à charge','vesper',null,'images/Ash.jpeg','PNJ/Contact-Ash-Personne à charge.jpeg','{"nom":"Ash","role":"Personne à charge","identite_civile":"Ethan Mizuhara (nom d''usage ; identité d''origine inconnue)","metatype":"Humain","affiliation":"Ancien sujet expérimental de Kagamori Biosystems","statut":"Sous la protection de Vesper","description":"Ash est un ancien sujet expérimental de Kagamori Biosystems. Éveillé, il était destiné à devenir le résultat d''un programme de recherche dont les objectifs exacts restent obscurs. Mais l''expérience n''a jamais produit les résultats escomptés.\n\nConsidéré comme un échec par ses créateurs, Ash avait été condamné à la destruction.\n\nLorsque Naoko et Ren ont organisé leur fuite, ils ont décidé de ne pas l''abandonner. Ash a ainsi échappé au sort qui l''attendait et découvert, pour la première fois, une existence qui ne soit pas entièrement dictée par les protocoles d''un laboratoire.\n\nSon identité véritable demeure inconnue. Après son évasion, il a adopté le nom de famille de Naoko, Mizuhara, ainsi qu''un prénom américain, Ethan. Il reste néanmoins connu sous le surnom d''Ash.\n\nAujourd''hui, il vit discrètement chez Vesper, aux côtés de Naoko. Ren assure leur protection et dissimule leur présence à son entourage, y compris à Aya."}'::jsonb),
('contact:edward-hudson','Edward Hudson','Armurier','vesper',null,'images/Edward Hudson.jpeg','PNJ/Contact-Edward Hudson-Armurier.jpeg','{"identite_civile":"Edward Hudson","metatype":"Nain","affiliation":"Inconnue","statut":"Actif","description":"Edward Hudson est un vendeur d''armes auprès duquel Vesper s''approvisionne régulièrement. Fournisseur fiable et discret, il privilégie les relations commerciales efficaces et évite les questions superflues.\n\nVesper compte parmi ses bons clients. Leur relation repose sur une confiance professionnelle et une appréciation mutuelle de la discrétion.","premiere_apparition":null,"reseau":5,"loyaute":3}'::jsonb),
('contact:hiroshi-takamura','Hiroshi Takamura','Wakagashira-hosa / Lieutenant Yakuza','vesper',null,'images/Hiroshi Takamura.jpeg','PNJ/Contact-Hiroshi Takamura-Yakusa.jpeg','{"nom":"Hiroshi Takamura","role":"Wakagashira-hosa / Lieutenant Yakuza","identite_civile":"Hiroshi Takamura (高村 浩)","metatype":"Humain","age":"54 ans","affiliation":"Clan Shotozumi, Seattle","statut":"Actif","description":"Surnommé « Hiro-san », Hiroshi Takamura est un wakagashira-hosa, lieutenant du clan Shotozumi à Seattle. Élégant, cultivé et étonnamment chaleureux, il est grand amateur de whiskies japonais et possède une impressionnante collection de bouteilles rares. Il aime plaisanter, raconter des anecdotes et débattre pendant des heures des mérites respectifs du Yamazaki et du Hibiki.\n\nDerrière cette bonhomie se cache un lieutenant respecté, capable d''une froideur absolue lorsque les intérêts de son clan sont menacés. Il accorde une importance considérable à la loyauté, à la parole donnée et au respect.\n\nHiroshi a rencontré Vesper lors d''une dégustation improvisée dans un petit bar japonais de Seattle. Une discussion sur un whisky tourbé s''est prolongée jusqu''à la fermeture. Il apprécie la courtoisie de Ren, son calme et sa conception du Bushidō, et l''appelle affectueusement « Ren-kun ».\n\nDepuis, ils partagent régulièrement une bouteille et parlent rarement de leurs métiers. Hiroshi sait que Ren travaille dans les Ombres, mais ne lui pose aucune question indiscrète. Il peut lui apporter des renseignements sur le milieu criminel japonais, faciliter certaines rencontres ou intervenir discrètement en sa faveur.","premiere_apparition":null,"reseau":7,"loyaute":5}'::jsonb),
('contact:ichida-takako','Ichida Takako','Corpo','vesper',null,'images/Ichida Takako.jpeg','PNJ/Contact-Ichida Takako-Corpo.jpeg','{"identite_civile":"Ichida Takako (市田 貴子)","metatype":"Elfe","age":"45 ans","affiliation":"Filiale de Shiawase","statut":"Active","description":"Ichida Takako travaille pour une filiale de Shiawase et dispose d''un vaste réseau de relations dans le milieu corporatiste.\n\nElle a rencontré Vesper dans un bar. Leur rencontre a débouché sur une courte liaison qui n''a finalement connu aucune suite sentimentale. Ils sont néanmoins restés en bons termes et ont conservé le contact.","premiere_apparition":null,"reseau":5,"loyaute":6}'::jsonb),
('contact:naoko-mizuhara','Naoko Mizuhara','Scientifique / Personne à charge','vesper',null,'images/Naoko Mizuhara.jpeg','PNJ/Contact-Naoko-Personne à charge.jpeg','{"nom":"Naoko Mizuhara","role":"Scientifique / Personne à charge","identite_civile":"Naoko Mizuhara (水原 直子)","metatype":"Elfe","affiliation":"Anciennement Kagamori Biosystems (projet Gemini)","statut":"Active, sous la protection de Vesper","description":"Naoko Mizuhara est une scientifique elfe spécialisée dans l''étude de la métahumanité et des phénomènes magiques. Ancienne chercheuse chez Kagamori Biosystems, elle a participé au projet Gemini, un programme expérimental dont Ren et Aya Kagami étaient les sujets.\n\nPendant des années, elle les a observés, étudiés et côtoyés dans le cadre de ses recherches. Mais là où ses supérieurs ne voyaient que des sujets d''expérimentation, Naoko a progressivement reconnu deux enfants privés de liberté et d''avenir.\n\nPrise de compassion pour eux, elle a fini par prendre une décision qui allait bouleverser leurs existences : les aider à s''évader.\n\nAujourd''hui, Naoko vit discrètement chez Vesper, aux côtés d''Ash. Ren veille personnellement à leur sécurité et garde leur présence secrète, y compris auprès de sa propre sœur, Aya."}'::jsonb),
('contact:razor','Razor','Ganger','vesper',null,'images/Razor.jpeg','PNJ/Contact-Razor-Ganger.jpeg','{"identite_civile":"Inconnue","metatype":"Troll","affiliation":"Gang non identifié","statut":"Actif","description":"Razor est un ganger troll au tempérament particulièrement territorial. Sa première rencontre avec Vesper aurait pu très mal se terminer : Razor comptait corriger personnellement ce petit elfe qui avait eu l''audace de traverser son territoire.\n\nL''arrivée d''un gang rival changea cependant la situation. Malgré leur infériorité numérique, Vesper choisit de combattre aux côtés de Razor plutôt que de l''abandonner. Depuis cet affrontement, les deux hommes entretiennent une amitié aussi improbable que sincère.","premiere_apparition":null,"reseau":3,"loyaute":5}'::jsonb),
('contact:yuki-stardust','Yuki Stardust','Chanteuse de JPop','vesper',null,'images/Yuki Stardust.jpg','PNJ/Contact-Yuki Stardust-Chanteuse de JPop.jpg','{"identite_civile":"Hoshino Akari (星野 明里)","metatype":"Elfe","affiliation":"Scène musicale underground","statut":"Active","description":"Yuki Stardust est une chanteuse de J-pop underground au style excentrique. Vesper l''a rencontrée au cours de ses nombreuses sorties en discothèque, alors qu''il découvrait une vie bien éloignée de celle qu''il avait connue jusque-là.\n\nIl l''a un jour débarrassée d''un stalker importun. Depuis, ils se connaissent, sans pour autant entretenir une relation particulièrement proche.","premiere_apparition":null,"reseau":2,"loyaute":2}'::jsonb),
